    def esc(c: str) -> str:
        return "\\" + c if c in "()\\" else c

    def encode_run(c: str, n: int) -> str:
        e = esc(c)
        parts = []
        while n > 99:
            parts.append(f"(99*{e})")
            n -= 99
        if n >= 3:
            parts.append(f"({n}*{e})")
        else:
