    s = serial[:8].upper()
    total = 0
    for i, c in enumerate(reversed(s)):
        v = ord(c) - (ord('0') if c.isdigit() else ord('A') - 10)
        if i % 2 == 0:
            v *= 2
            if v >= 36:
                v -= 35
        total += v
    check = (-total) % 36
    if check < 10:
        ch = str(check)
    else:
        ch = chr(ord('A') + check - 10)
    return s[:0] and serial or (serial[:8] + ch)

