def format_duration(seconds: int) -> str:
    seconds = int(seconds)
    if seconds == 0:
        return "now"

    units = [
        (365 * 24 * 3600, "year"),
        (24 * 3600, "day"),
        (3600, "hour"),
        (60, "minute"),
        (1, "second"),
    ]

    parts = []
    for value, name in units:
        count = seconds // value
        if count > 0:
            parts.append(f"{count} {name}" + ("" if count == 1 else "s"))
            seconds %= value

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-1]) + " and " + parts[-1]

